num_golfers = 36
num_weeks = 6
num_groups = 9
group_size = 4

# Verify solution
# Check each week has exactly 4 golfers per group
for w in range(num_weeks):
    week_groups = solution[w*36:(w+1)*36]
    for g in range(num_groups):
        count = week_groups.count(g)
        if count != group_size:
            print(f"Week {w}, Group {g}: {count} golfers (expected {group_size})")

# Check no pair appears together more than once
from collections import defaultdict
pair_count = defaultdict(int)
for w in range(num_weeks):
    week_groups = solution[w*36:(w+1)*36]
    for g in range(num_groups):
        golfers_in_group = [p for p in range(num_golfers) if week_groups[p] == g]
        for i in range(len(golfers_in_group)):
            for j in range(i+1, len(golfers_in_group)):
                pair = (golfers_in_group[i], golfers_in_group[j])
                pair_count[pair] += 1

violations = [(pair, count) for pair, count in pair_count.items() if count > 1]
if violations:
    print(f"Found {len(violations)} pair violations!")
    for pair, count in violations[:5]:
        print(f"  Pair {pair}: {count} times")
else:
    print("All constraints satisfied!")
    print(f"Total unique pairs covered: {len(pair_count)}")
    print(f"Total possible pairs: {num_golfers*(num_golfers-1)//2}")
